/* ── JLS §3.2 step 1 / §3.3: Unicode escape translation ──────────────────────────────
   "A raw Unicode character stream is translated into a sequence of Java tokens, using the
   following three lexical translation steps, which are applied IN TURN: 1. A translation of
   Unicode escapes (§3.3) in the raw stream ... 2. ... line terminators ... 3. ... tokens."

   Step 1 runs over the WHOLE source before anything is tokenized, which is why \u0041 can
   spell an identifier and \u0069\u006e\u0074 can spell `int`. Handling \u only inside string
   and character literals — where this compiler handled it — implements none of that.

   The three rules that make it correct, §3.3 verbatim:

     eligibility  "for each raw input character that is a backslash \, input processing must
                  consider how many other \ characters contiguously precede it ... If this
                  number is even, then the \ is eligible to begin a Unicode escape; if the
                  number is odd, then the \ is not eligible."
                  So "\\u2297=\u2297" is the eleven characters " \ \ u 2 2 9 7 = ⊗ ".

     malformed    "If an eligible \ is followed by u, or more than one u, and the last u is
                  not followed by four hexadecimal digits, then a compile-time error occurs."

     no re-entry  "The character produced by a Unicode escape does not participate in further
                  Unicode escapes ... \u005cu005a results in the six characters \ u 0 0 5 a
                  ... It does not result in the character Z."
                  Falls out structurally: a translation is only ever attempted at a backslash
                  READ FROM THE INPUT, and an emitted character is never re-examined.

   The escape's character is emitted as UTF-8, so the rest of the pipeline sees exactly what
   it would have seen had the character been written literally. Output is never longer than
   input (6+ source bytes → at most 3). One caveat, stated rather than hidden: a line whose
   escapes are shorter after translation reports shifted COLUMNS in diagnostics; line numbers
   are unaffected, except that \u000a really does become a line terminator, which is §3.4's
   rule and not an accident. */
static inline int juni_hex(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

/* Translate `src` into a fresh malloc'd buffer (caller frees). On a malformed escape returns
 * NULL and points *err at a message — §3.3 makes that a compile-time error, not a pass-through. */
static inline char* java_unicode_translate(const char* src, int len, int* out_len, const char** err) {
    char* out = (char*)malloc((size_t)len + 1);
    if (!out) { *err = "out of memory"; return NULL; }
    int i = 0, o = 0, bs = 0;    /* bs: contiguous backslashes immediately before src[i] */
    while (i < len) {
        char c = src[i];
        if (c == '\\' && (bs % 2) == 0 && i + 1 < len && src[i + 1] == 'u') {
            int j = i + 1;
            while (j < len && src[j] == 'u') j++;        /* UnicodeMarker: u | UnicodeMarker u */
            int v = 0, k = 0;
            for (; k < 4; k++) {
                int h = (j + k < len) ? juni_hex(src[j + k]) : -1;
                if (h < 0) { free(out); *err = "malformed \\u escape: expected four hex digits"; return NULL; }
                v = (v << 4) | h;
            }
            if (v < 0x80) out[o++] = (char)v;
            else if (v < 0x800) { out[o++] = (char)(0xC0 | (v >> 6));
                                  out[o++] = (char)(0x80 | (v & 0x3F)); }
            else { out[o++] = (char)(0xE0 | (v >> 12));
                   out[o++] = (char)(0x80 | ((v >> 6) & 0x3F));
                   out[o++] = (char)(0x80 | (v & 0x3F)); }
            i = j + 4;
            bs = 0;                                       /* the produced char does not participate */
            continue;
        }
        out[o++] = c;
        bs = (c == '\\') ? bs + 1 : 0;
        i++;
    }
    out[o] = 0;
    *out_len = o;
    return out;
}

